package com.pp.shaderlod.optimization.sildurpixel.mixin;import com.pp.shaderlod.optimization.sildurpixel.SildurPixelRuntime;import net.irisshaders.iris.targets.RenderTargets;import net.irisshaders.iris.pipeline.CompositeRenderer;import org.spongepowered.asm.mixin.*;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(targets="net.irisshaders.iris.pipeline.IrisRenderingPipeline",remap=false)public abstract class SildurPixelPipelineMixin{@Shadow @Final private RenderTargets renderTargets;@Shadow @Final private CompositeRenderer compositeRenderer;@Inject(method="beginLevelRendering()V",at=@At("RETURN"),require=1)private void begin(CallbackInfo c){SildurPixelRuntime.begin(this,renderTargets,compositeRenderer);}@Inject(method="destroy()V",at=@At("HEAD"),require=1)private void destroy(CallbackInfo c){SildurPixelRuntime.invalidate();}}